BUNDLES['build_macro_monitor.py'] = ('macro-early-warning-dashboard', BUILD_MACRO_MONITOR_PY)

def _write(path, b64):
    with open(path, "wb") as fh:
        fh.write(gzip.decompress(base64.b64decode(b64)))

def main():
    names = sorted(BUNDLES)
    if "--list" in sys.argv:
        for i, n in enumerate(names, 1):
            print(f"{i}. {n}  ->  {BUNDLES[n][0]}/")
        return 0
    _write(os.path.join(os.getcwd(), "control_center.py"), CC_B64)
    print("wrote control_center.py")
    if "--all" in sys.argv:
        chosen = names
    else:
        for i, n in enumerate(names, 1):
            print(f"  {i}. {n}")
        raw = input("Build which? (numbers space-separated, or a=all): ").strip()
        chosen = names if raw.lower() in ("a", "all") else \
            [names[int(x) - 1] for x in raw.split()]
    for n in chosen:
        folder, b64 = BUNDLES[n]
        os.makedirs(folder, exist_ok=True)
        dest = os.path.join(folder, n)
        _write(dest, b64)
        print(f"== building {n} in {folder}/ ==")
        r = subprocess.run([sys.executable, n], cwd=folder)
        if r.returncode != 0:
            print(f"   FAILED (exit {r.returncode}) -- fix and rerun; continuing")
    print("Done. Next: python control_center.py")
    return 0

if __name__ == "__main__":
    try:
        sys.exit(main())
    except ImportError as e:
        sys.stderr.write("Missing dependency: %s\nRun: python -m pip install pandas openpyxl\n" % e)
        sys.exit(1)
